<section class="fviii-metrics"><div><b><?= (int)$counts['open'] ?></b><span>Pools abertos</span></div><div><b><?= (int)$counts['eligible'] ?></b><span>Unidades aguardando definição</span></div><div><b><?= (int)$counts['individual'] ?></b><span>Retestes individuais</span></div></section>
<section class="content-card qc-filter-card"><form class="qc-filters fviii-filters" method="get"><label><span>Hemocomponente</span><select name="component"><option value="">PFC e PFC24</option><?php foreach($components as $c):?><option value="<?= $c['id'] ?>" <?=$filters['component']==$c['id']?'selected':''?>><?=htmlspecialchars($c['code'].' — '.$c['name'])?></option><?php endforeach;?></select></label><label><span>Origem / processamento</span><select name="origin"><option value="">Todas</option><?php foreach($origins as $o):?><option value="<?=$o['id']?>" <?=$filters['origin']==$o['id']?'selected':''?>><?=htmlspecialchars($o['name'])?></option><?php endforeach;?></select></label><label><span>De</span><input type="date" name="from" value="<?=htmlspecialchars($filters['from'])?>"></label><label><span>Até</span><input type="date" name="to" value="<?=htmlspecialchars($filters['to'])?>"></label><label><span>Status</span><select name="status"><option value="">Todos</option><?php foreach($statusLabels as $k=>$v):?><option value="<?=$k?>" <?=$filters['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label><span>Código do pool</span><input name="code" value="<?=htmlspecialchars($filters['code'])?>"></label><div class="qc-filter-actions"><button class="button button-compact">Filtrar</button><a class="button button-secondary button-compact" href="/quality-control/factor-viii-pools">Limpar</a></div></form></section>
<?php if($canCreate):?><section class="content-card fviii-generator"><div><h2>Formação automática</h2><p>Agrupamento determinístico por hemocomponente e origem, com até <?=\BloodHub\Services\FactorViiiPoolService::FVIII_POOL_MAX_SIZE?> unidades.</p></div><form method="post" action="/quality-control/factor-viii-pools/preview"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="component" value="<?=htmlspecialchars($filters['component'])?>"><input type="hidden" name="origin" value="<?=htmlspecialchars($filters['origin'])?>"><input type="hidden" name="from" value="<?=htmlspecialchars($filters['from'])?>"><input type="hidden" name="to" value="<?=htmlspecialchars($filters['to'])?>"><button class="button">Gerar pools</button></form></section><?php endif;?>
<?php if($preview):?><section class="content-card fviii-preview"><header><div><h2>Prévia da geração</h2><p>Nada foi persistido. Confirme somente após revisar tipo, origem e unidades.</p></div><div><form method="post" action="/quality-control/factor-viii-pools/preview/discard"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><button class="button button-secondary">Cancelar</button></form><form method="post" action="/quality-control/factor-viii-pools/create"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><button class="button">Confirmar geração</button></form></div></header><div class="fviii-preview-grid"><?php foreach($preview['pools'] as $i=>$pool):?><article><strong>Pool <?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></strong><span><?=$pool['component_code']?> · <?=htmlspecialchars($pool['origin_name'])?></span><ol><?php foreach($pool['samples'] as $s):?><li><?=htmlspecialchars($s['donation_number']?:$s['sample_code']??('#'.$s['id']))?> <small><?=htmlspecialchars($s['lcqh_code'])?></small></li><?php endforeach;?></ol></article><?php endforeach;?></div></section><?php endif;?>
<form method="post" action="/quality-control/factor-viii-pools/save-all"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><section class="content-card fviii-table-card"><header><div><h2>Pools de Fator VIII</h2><p>Resultado em UI/mL; vírgula e ponto são aceitos.</p></div><div><?php if($canResult):?><button class="button button-secondary button-compact">Salvar todos</button><button class="button button-compact" name="complete" value="1">Concluir todos preenchidos</button><?php endif;?><a class="button button-secondary button-compact" href="/quality-control/factor-viii-pools/map" target="_blank">Imprimir mapa</a></div></header><div class="table-responsive"><table class="fviii-table"><thead><tr><th>Pool</th><th>Tipo</th><th>Origem</th><th>Unidades</th><th>Resultado FVIII</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($pools as $pool):$members=array_filter(explode(';;',(string)$pool['member_labels']));?><tr><td><strong><?=htmlspecialchars($pool['code'])?></strong><small><?=date('d/m/Y H:i',strtotime($pool['created_at']))?></small></td><td><?=$pool['component_code']?></td><td><?=htmlspecialchars($pool['origin_name'])?></td><td><div class="fviii-chips"><?php foreach($members as $m):[$don,$lcqh]=array_pad(explode('|',$m,2),2,'');?><span title="LCQH: <?=htmlspecialchars($lcqh)?>"><?=htmlspecialchars($don)?></span><?php endforeach;?></div></td><td><?php if($pool['status']==='open'&&$canResult):?><input class="fviii-result-input" inputmode="decimal" name="pools[<?=$pool['id']?>]" value="<?=$pool['result']!==null?number_format((float)$pool['result'],2,',',''):''?>" placeholder="0,00"><small>UI/mL</small><?php else:?><b><?=$pool['result']!==null?number_format((float)$pool['result'],2,',','.').' UI/mL':'—'?></b><?php endif;?></td><td><span class="fviii-status <?=$pool['status']?>"><?=$statusLabels[$pool['status']]?></span></td><td><div class="fviii-actions"><?php if($pool['status']==='open'&&$canResult):?><button class="button button-secondary button-compact" formaction="/quality-control/factor-viii-pools/result" name="pool_id" value="<?=$pool['id']?>">Salvar</button><button class="button button-compact" formaction="/quality-control/factor-viii-pools/result" name="pool_id" value="<?=$pool['id']?>" data-complete-pool>Concluir</button><?php endif;?><a class="button button-secondary button-compact" href="/quality-control/factor-viii-pools/map?ids=<?=$pool['id']?>" target="_blank">Mapa</a><?php if($pool['status']==='open'&&$canCancel):?><button type="button" class="button button-danger button-compact" data-cancel-pool="<?=$pool['id']?>">Cancelar</button><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$pools):?><tr><td colspan="7" class="qc-empty">Nenhum pool encontrado.</td></tr><?php endif;?></tbody></table></div></section></form>
<dialog id="fviii-cancel"><form method="post" action="/quality-control/factor-viii-pools/cancel"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="pool_id"><h2>Cancelar pool aberto</h2><p>O histórico será preservado e as unidades voltarão à elegibilidade.</p><label><span>Motivo obrigatório</span><textarea name="reason" maxlength="500" required></textarea></label><div><button type="button" class="button button-secondary" onclick="this.closest('dialog').close()">Voltar</button><button class="button button-danger">Confirmar cancelamento</button></div></form></dialog>
<script>document.querySelectorAll('[data-cancel-pool]').forEach(b=>b.onclick=()=>{const d=document.querySelector('#fviii-cancel');d.querySelector('[name=pool_id]').value=b.dataset.cancelPool;d.showModal()});document.querySelectorAll('[data-complete-pool]').forEach(b=>b.onclick=e=>{const input=b.closest('tr').querySelector('.fviii-result-input');if(!input.value.trim()){e.preventDefault();input.focus();return}b.name='complete';b.value='1';const hidden=document.createElement('input');hidden.type='hidden';hidden.name='pool_id';hidden.value=b.closest('tr').querySelector('[name^="pools["]').name.match(/\d+/)[0];b.form.append(hidden)});</script>
